import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import { cn } from "@/lib/utils";
import { forwardRef } from "react";

type CodeProps = React.HTMLAttributes<HTMLElement>;

const Code = forwardRef<HTMLElement, CodeProps>(({ className, ...props }, ref) => {
  return (
    <code
      ref={ref}
      className={cn(
        "rounded-sm border border-border bg-accent/10 px-1.5 py-0.5 font-mono text-sm text-accent",
        className,
      )}
      {...props}
    />
  );
});
Code.displayName = "Code";

export { Code };

import { forwardRef } from "react";

import { CopyButton } from "@/components/CopyButton";
import { cn } from "@/lib/utils";
import { tokenizeBrackets } from "@/lib/tokenizeBrackets";

interface CodeBlockProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The code to render and optionally copy. Preserve whitespace exactly as written. */
  code: string;
  /** Optional language label shown in the top-left corner (e.g. "bash", "tsx"). */
  language?: string;
  /** Whether to render the overlay copy button. Defaults to true. */
  showCopy?: boolean;
}

/**
 * Multi-line code display. Uses `--surface` (not `--card`) to keep it positioned as
 * content, not an elevated container. Overflow is horizontal-scroll only — never wrap.
 */
const CodeBlock = forwardRef<HTMLDivElement, CodeBlockProps>(
  ({ code, language, showCopy = true, className, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn(
          "group relative rounded-lg bg-surface",
          language ? "pt-8 pb-4" : "py-4",
          "px-4",
          className,
        )}
        {...props}
      >
        {language && (
          <span className="absolute left-3 top-2 font-mono text-xs text-foreground-muted">
            {language}
          </span>
        )}
        {showCopy && (
          <CopyButton
            variant="ghost"
            value={code}
            label={language ? `${language} snippet` : "code snippet"}
            className="absolute right-2 top-2 h-9 w-9 min-h-0 min-w-0 opacity-50 transition-opacity duration-100 group-hover:opacity-100 focus-visible:opacity-100"
          />
        )}
        <pre
          role="code"
          className="overflow-x-auto whitespace-pre font-mono text-sm text-foreground"
        >
          {tokenizeBrackets(code)}
        </pre>
      </div>
    );
  },
);
CodeBlock.displayName = "CodeBlock";

export { CodeBlock };
export type { CodeBlockProps };

import React from "react";

const SPLIT_RE = /(\[[^\]\n]+\])/g;
const MATCH_RE = /^\[[^\]\n]+\]$/;

const HIGHLIGHT_CLASS = "rounded-sm bg-accent/10 px-1 text-accent";

/**
 * Splits `text` on [bracketed] tokens and wraps each match in a highlighted span.
 * Plain segments are returned as strings. The raw `text` is unchanged and should
 * be used as the copy-to-clipboard value.
 */
export function tokenizeBrackets(text: string): React.ReactNode[] {
  const parts = text.split(SPLIT_RE);
  return parts.map((part, i) =>
    MATCH_RE.test(part) ? (
      <span key={i} className={HIGHLIGHT_CLASS}>
        {part}
      </span>
    ) : (
      part
    ),
  );
}

import { Check, Copy } from "lucide-react";
import { forwardRef, useRef, useState } from "react";

import { cn } from "@/lib/utils";

interface CopyButtonProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "value"> {
  /** Text copied to the clipboard when the button is clicked. */
  value: string;
  /** Primary shows label + icon with accent background; ghost is icon-only, typically overlaid on a CodeBlock. */
  variant: "primary" | "ghost";
  /** Visible text for the primary variant. Defaults to `value`. Ignored for ghost. */
  label?: string;
}

const COPIED_DURATION_MS = 2000;

const CopyButton = forwardRef<HTMLButtonElement, CopyButtonProps>(
  ({ value, variant, label, className, onClick, ...props }, ref) => {
    const [copied, setCopied] = useState(false);
    const buttonRef = useRef<HTMLButtonElement | null>(null);

    const handleClick = async (e: React.MouseEvent<HTMLButtonElement>) => {
      onClick?.(e);
      try {
        await navigator.clipboard.writeText(value);
        setCopied(true);
        setTimeout(() => setCopied(false), COPIED_DURATION_MS);
      } catch {
        // Fallback: select the nearest <pre> for manual Cmd/Ctrl+C.
        const target = buttonRef.current;
        const pre = target?.closest("div")?.querySelector("pre");
        if (pre) {
          const range = document.createRange();
          range.selectNodeContents(pre);
          const selection = window.getSelection();
          selection?.removeAllRanges();
          selection?.addRange(range);
        }
      }
    };

    const Icon = copied ? Check : Copy;
    const displayLabel = variant === "primary" ? (copied ? "Copied!" : (label ?? value)) : null;
    const ariaLabel = copied ? "Copied to clipboard" : `Copy ${label ?? value} to clipboard`;

    const baseClasses =
      "inline-flex items-center justify-center gap-2 rounded-md font-mono text-sm transition-[filter,background-color,color] duration-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-accent focus-visible:outline-offset-2 disabled:pointer-events-none disabled:opacity-50";

    const variantClasses =
      variant === "primary"
        ? "min-h-[44px] bg-accent text-accent-foreground px-4 py-2 hover:brightness-110 active:scale-[0.98]"
        : "h-11 w-11 min-h-[44px] min-w-[44px] bg-transparent text-foreground-muted hover:bg-surface hover:text-foreground";

    return (
      <button
        ref={(node) => {
          buttonRef.current = node;
          if (typeof ref === "function") ref(node);
          else if (ref) ref.current = node;
        }}
        type="button"
        onClick={handleClick}
        aria-label={ariaLabel}
        className={cn(baseClasses, variantClasses, className)}
        {...props}
      >
        <Icon className="h-4 w-4" aria-hidden="true" />
        {displayLabel && <span className="truncate">{displayLabel}</span>}
        <span className="sr-only" aria-live="polite">
          {copied ? "Copied to clipboard" : ""}
        </span>
      </button>
    );
  },
);
CopyButton.displayName = "CopyButton";

export { CopyButton };
export type { CopyButtonProps };

import { cn } from "@/lib/utils";
import { forwardRef } from "react";

type HeadingLevel = "h1" | "h2" | "h3" | "h4";

interface HeadingProps extends React.HTMLAttributes<HTMLHeadingElement> {
  level?: HeadingLevel;
  as?: HeadingLevel;
}

const headingStyles: Record<HeadingLevel, string> = {
  h1: "text-2xl font-semibold font-display tracking-tight text-wrap-balance",
  h2: "text-xl font-medium font-display tracking-tight text-wrap-balance",
  h3: "text-md font-medium font-display",
  h4: "text-sm font-medium font-display uppercase tracking-widest text-muted-foreground",
};

/** No icons allowed inside headings — use Text or a wrapper instead. */
const Heading = forwardRef<HTMLHeadingElement, HeadingProps>(
  ({ level = "h2", as, className, children, ...props }, ref) => {
    const Tag = as || level;
    return (
      <Tag ref={ref} className={cn(headingStyles[level], className)} {...props}>
        {children}
      </Tag>
    );
  },
);
Heading.displayName = "Heading";

export { Heading };
export type { HeadingProps, HeadingLevel };

