          size="sm"
          className="h-7 px-2 text-xs font-display"
          onClick={() => setTheme(value)}
          aria-label={`Switch to ${label} theme${isDefault ? " (default)" : ""}`}
        >
          <Icon className="h-3 w-3 sm:mr-1" />
          <span className="hidden sm:inline">{label}</span>
        </Button>
      ))}
    </div>
