import { createContext, useContext, useEffect, useState, ReactNode } from "react";

type Theme = "dark" | "light" | "warm";

interface ThemeContextType {
  theme: Theme;
  setTheme: (theme: Theme) => void;
}

const ThemeContext = createContext<ThemeContextType>({ theme: "warm", setTheme: () => {} });

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<Theme>(() => {
    try {
      const stored = localStorage.getItem("democrito-theme") as Theme | null;
      return stored || "warm";
    } catch {
      return "warm";
    }
  });

  useEffect(() => {
    const root = document.documentElement;
    root.classList.remove("dark", "light", "warm");
    root.classList.add(theme);
    localStorage.setItem("democrito-theme", theme);
  }, [theme]);

  return (
    <ThemeContext.Provider value={{ theme, setTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

export const useTheme = () => useContext(ThemeContext);

import { cn } from "@/lib/utils";
import { Progress } from "@/components/ui/progress";

interface TokenCounterProps {
  current: number;
  max: number;
  compact?: boolean;
  className?: string;
}

export function TokenCounter({ current, max, compact, className }: TokenCounterProps) {
  const ratio = current / max;
  const variant = ratio > 0.9 ? "error" : ratio > 0.75 ? "warning" : "default";

  return (
    <span className={cn("inline-flex items-center gap-2", className)}>
      <span className={cn(
        "font-mono text-xs",
        variant === "error" && "text-error",
        variant === "warning" && "text-warning",
        variant === "default" && "text-muted-foreground",
      )}>
        {compact ? current.toLocaleString() : `${current.toLocaleString()} tokens`}
      </span>
      <Progress value={ratio * 100} variant={variant === "default" ? "default" : variant} className="w-[60px] h-[3px]" />
    </span>
  );
}

